import { motion } from 'framer-motion';
import { Sun, Moon, Menu, X } from 'lucide-react';
import { useEffect, useState } from 'react';
import useTheme from '../hooks/useTheme';
import logo from '../assets/logo.png';

const links = [
  { name: 'Home', href: '#hero' },
  { name: 'About', href: '#hero' }, // Points to Home as requested
  { name: 'Skills', href: '#skills' },
  { name: 'Projects', href: '#projects' },
  { name: 'Work Experience', href: '#work-experience' },
  { name: 'Contact', href: '#contact' },
];

export default function Navbar() {
  const [activeSection, setActiveSection] = useState('hero');
  const [menuOpen, setMenuOpen] = useState(false);
  const { theme, toggleTheme } = useTheme();

  useEffect(() => {
    const sections = document.querySelectorAll('section[id]');
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) setActiveSection(entry.target.id);
        });
      },
      { rootMargin: '-50% 0px -50% 0px', threshold: 0 }
    );
    sections.forEach((section) => observer.observe(section));
    return () => observer.disconnect();
  }, []);

  return (
    <motion.nav
      initial={{ opacity: 0, y: -20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
      className="fixed top-0 left-0 w-full bg-white/70 dark:bg-black/70 backdrop-blur-md shadow-md z-50"
    >
      <div className="max-w-6xl mx-auto flex justify-between items-center px-6 py-4">
        {/* Left: Logo */}
        <a href="#hero" className="flex items-center gap-2">
          {logo ? (
            <img src={logo} alt="Logo" className="w-10 h-10 object-contain" />
          ) : (
            <h1 className="text-xl font-bold dark:text-white">Abdul Razack</h1>
          )}
        </a>

        {/* Right: Desktop links and theme button */}
        <div className="flex items-center gap-4 justify-end">
          {/* Desktop links */}
          <ul className="hidden md:flex gap-6 text-gray-700 dark:text-gray-300 font-medium ">
            {links.map((link) => (
              <li key={link.name}> {/* Use name as key since hrefs might be duplicate */}
                <a
                  href={link.href}
                  className={`transition-colors ${(activeSection === link.href.replace('#', '') || (link.name === 'About' && activeSection === 'hero'))
                      ? 'text-black dark:text-white font-semibold'
                      : 'hover:text-black dark:hover:text-white'
                    }`}
                >
                  {link.name}
                </a>
              </li>
            ))}
          </ul>

          {/* Theme button */}
          <button
            onClick={toggleTheme}
            className="p-2 rounded-full bg-gray-200 dark:bg-gray-700 text-black dark:text-white hover:scale-110 transition"
          >
            {theme === 'light' ? <Moon className="w-5 h-5" /> : <Sun className="w-5 h-5" />}
          </button>

          {/* Mobile menu icon */}
          <button
            className="md:hidden p-2 rounded-full bg-gray-200 dark:bg-gray-700 text-black dark:text-white hover:scale-110 transition"
            onClick={() => setMenuOpen(!menuOpen)}
          >
            {menuOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}
          </button>
        </div>
      </div>

      {/* Mobile menu */}
      {menuOpen && (
        <div className="md:hidden bg-white dark:bg-black w-full ml-auto shadow-md">
          <ul className="flex flex-col items-center gap-4 py-4 text-gray-700 dark:text-gray-300 font-medium">
            {links
              .filter((link) => link.name !== 'Projects') // Projects already in center?? removing this filter logic as it might be specific to previous design
              .map((link) => (
                <li key={link.name}>
                  <a
                    href={link.href}
                    className={`transition-colors ${(activeSection === link.href.replace('#', '') || (link.name === 'About' && activeSection === 'hero'))
                        ? 'text-black dark:text-white font-semibold'
                        : 'hover:text-black dark:hover:text-white'
                      }`}
                    onClick={() => setMenuOpen(false)}
                  >
                    {link.name}
                  </a>
                </li>
              ))}
            {/* Add Projects link back for mobile if filter removed */}
            <li key="Projects-mobile">
              <a
                href="#projects"
                className={`transition-colors ${activeSection === 'projects'
                    ? 'text-black dark:text-white font-semibold'
                    : 'hover:text-black dark:hover:text-white'
                  }`}
                onClick={() => setMenuOpen(false)}
              >
                Projects
              </a>
            </li>
          </ul>
        </div>
      )}
    </motion.nav>
  );
}
